sys_script_include.script:
(function transform(transformBuilder, transformScriptArgs) {
    try {
        if (!transformBuilder) return;

        var listModel = transformBuilder

        // do not remove
        .transform();

        /************************************************************
         * Record List 3:
         * Only Quarter field editable
         * All other fields read-only
         ************************************************************/

        // IMPORTANT:
        // Replace this with actual backend field name if different
        var editableField = 'quarter';
        // Example if field is custom:
        // var editableField = 'u_quarter';

        // Make only Quarter column editable
        if (listModel.columnDefinitions && listModel.columnDefinitions.columns) {
            listModel.columnDefinitions.columns.forEach(function(column) {

                var isEditableColumn = column.key === editableField;

                column.editable = isEditableColumn;
                column.readOnly = !isEditableColumn;
                column.disabled = !isEditableColumn;

            });
        }

        // Make only Quarter cells editable in every row
        if (listModel.rowDefinitions && listModel.rowDefinitions.rows) {
            listModel.rowDefinitions.rows.forEach(function(row) {

                if (!row.cells) return;

                Object.keys(row.cells).forEach(function(cellKey) {
                    var cell = row.cells[cellKey];
                    var isEditableCell = cellKey === editableField;

                    cell.editable = isEditableCell;
                    cell.readOnly = !isEditableCell;
                    cell.disabled = !isEditableCell;
                });

            });
        }

        return listModel;
    }

    catch (error) {
        return {
            failed: true,
            error: error.message
        };
    }
})(transformBuilder, transformScriptArgs);
